insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null), 1, 'bonjour-l-ecole', 'Bonjour l’école !', 'Comprendre les consignes de la classe, saluer, se présenter, présenter quelqu’un et prendre congé.', 1, 'published', 'Communication orale', '[{"title":"Curriculum de l’Éducation de Base, Langue et communication, étape 1, 2e version (MEN, avril 2014)","url":"http://svtdakar.e-monsite.com/medias/files/1.-langue-et-communication-1-efa.pdf","kind":"official"},{"title":"Guide pédagogique, enseignement élémentaire, 1re étape CI-CP (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%201.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
