insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'bonjour-l-ecole') and slug = 'les-consignes-de-la-classe'), $html$<p>En classe, le maître ou la maîtresse donne des <strong>consignes</strong>. Il faut les écouter et les faire.</p>
