insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-premiers-gestes-d-ecriture') and slug = 'les-outils-pour-ecrire'), $html$<p>Pour écrire, j’utilise l’<strong>ardoise</strong> et la <strong>craie</strong>, le <strong>cahier</strong> et le <strong>crayon</strong>.</p>
