insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'dire-ce-que-je-ressens-et-ce-que-j-aime') and slug = 'donner-son-avis-et-ses-preferences'), $html$<p>Chacun a ses goûts. On peut les dire avec respect.</p>
