insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-s-r-au-et-on'), 1, 'le-son-s', 'Le son s', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-s-r-au-et-on') and slug = 'le-son-s'), $html$<p>Écoute bien : on entend le son <strong>[s]</strong> dans « sac », « soleil », « salade », « Sokhna ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>s · S</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>sa · si · so · su · sou · sé · as · is</strong></p><p>Des mots : <strong>Sali · sous · soupe · salade</strong></p><p>Une phrase : <strong>Sali a salé la soupe.</strong></p><h2>J’écris</h2><p>Je trace un petit serpent : s.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends [s].</li><li>Cherche [s] dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-s-r-au-et-on'), 2, 'le-son-r', 'Le son r', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-s-r-au-et-on') and slug = 'le-son-r'), $html$<p>Écoute bien : on entend le son <strong>[r]</strong> dans « riz », « rue », « radio », « Rama ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>r · R</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>ra · ri · ro · ru · rou · ré · ar · or</strong></p><p>Des mots : <strong>rue · radio · Rama · route · mère · robe</strong></p><p>Une phrase : <strong>Rama a la robe de sa mère.</strong></p><h2>J’écris</h2><p>Je trace un petit trait, puis une petite vague en haut : r.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends [r].</li><li>Cherche [r] dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-s-r-au-et-on'), 3, 'le-son-au', 'Le son au', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-s-r-au-et-on') and slug = 'le-son-au'), $html$<p>Écoute bien : on entend le son <strong>[o] écrit au ou eau</strong> dans « auto », « bateau », « seau », « chaud ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>au · eau · o</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>tau · lau · pau · beau · deau · seau</strong></p><p>Des mots : <strong>auto · bateau · seau · rideau · taureau</strong></p><p>Une phrase : <strong>Papa a un beau bateau.</strong></p><h2>J’écris</h2><p>J’écris a et u collés pour au ; e, a et u pour eau.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends [o] écrit au ou eau.</li><li>Cherche [o] écrit au ou eau dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-s-r-au-et-on'), 4, 'le-son-on', 'Le son on', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-s-r-au-et-on') and slug = 'le-son-on'), $html$<p>Écoute bien : on entend le son <strong>[on]</strong> dans « mouton », « ballon », « pont », « nombre ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>on · om (devant m, b ou p)</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>ton · lon · mon · bon · son · ron · pom</strong></p><p>Des mots : <strong>mouton · ballon · bonbon · pompe · salon · rond</strong></p><p>Une phrase : <strong>Modou a un bonbon et un ballon rond.</strong></p><h2>J’écris</h2><p>J’écris o puis n : on. Devant b ou p, j’écris om : pompe.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends [on].</li><li>Cherche [on] dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
