insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null), 4, 'les-sons-v-w-et-oi', 'Les sons v, w et oi', 'Lire et écrire le son v (v, parfois w) et le son oi.', 4, 'published', 'Lecture', '[{"title":"Curriculum de l’Éducation de Base, Langue et communication, étape 1, 2e version (MEN, avril 2014)","url":"http://svtdakar.e-monsite.com/medias/files/1.-langue-et-communication-1-efa.pdf","kind":"official"},{"title":"Guide pédagogique, enseignement élémentaire, 1re étape CI-CP (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%201.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-v-w-et-oi'), 1, 'le-son-v', 'Le son v', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-v-w-et-oi') and slug = 'le-son-v'), $html$<p>Écoute bien : on entend le son <strong>v</strong> dans « vélo », « lave », « avion ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>v · V (et parfois w, comme dans wagon)</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>va · vi · vo · vu · vé · ve</strong></p><p>Des mots : <strong>vélo · lave · olive · lavabo · navire · valise</strong></p><p>Une phrase : <strong>Valérie a un vélo rouge.</strong></p><h2>J’écris</h2><p>Le v se trace comme une petite pointe : je descends, puis je remonte sans lever le crayon.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends v.</li><li>Cherche v dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-v-w-et-oi'), 2, 'le-son-oi', 'Le son oi', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-v-w-et-oi') and slug = 'le-son-oi'), $html$<p>Écoute bien : on entend le son <strong>oi</strong> dans « roi », « moi », « étoile ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>oi</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>moi · toi · roi · loi · noi · voi</strong></p><p>Des mots : <strong>roi · moi · toi · voile · étoile · boire</strong></p><p>Une phrase : <strong>Le roi voit une étoile.</strong></p><h2>J’écris</h2><p>Pour écrire oi, j’attache le o au i et je n’oublie pas le point sur le i.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends oi.</li><li>Cherche oi dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null), 5, 'les-sons-ch-et-e', 'Les sons ch et é', 'Lire le son ch, puis les différentes écritures du son é (é, er, ez, es).', 5, 'published', 'Lecture', '[{"title":"Curriculum de l’Éducation de Base, Langue et communication, étape 1, 2e version (MEN, avril 2014)","url":"http://svtdakar.e-monsite.com/medias/files/1.-langue-et-communication-1-efa.pdf","kind":"official"},{"title":"Guide pédagogique, enseignement élémentaire, 1re étape CI-CP (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%201.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-ch-et-e'), 1, 'le-son-ch', 'Le son ch', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-ch-et-e') and slug = 'le-son-ch'), $html$<p>Écoute bien : on entend le son <strong>ch</strong> dans « chat », « vache », « chocolat ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>ch (deux lettres pour un seul son)</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>cha · che · chi · cho · chou · chu</strong></p><p>Des mots : <strong>chat · chaton · vache · niche · chemise · mouche</strong></p><p>Une phrase : <strong>Le chat de Michel dort dans la niche.</strong></p><h2>J’écris</h2><p>J’écris ch avec deux lettres : le c, puis le h. Ensemble, elles font un seul son.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends ch.</li><li>Cherche ch dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-ch-et-e'), 2, 'les-ecritures-du-son-e', 'Les écritures du son é', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-ch-et-e') and slug = 'les-ecritures-du-son-e'), $html$<p>Écoute bien : on entend le son <strong>é</strong> dans « bébé », « nez », « manger ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>é · er · ez · es (dans les, des, mes, tes)</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>pé · té · ré · ter · rez · les</strong></p><p>Des mots : <strong>café · marcher · nez · chez · les · donner</strong></p><p>Une phrase : <strong>Le bébé va manger chez mémé.</strong></p><h2>J’écris</h2><p>À la fin d’un mot, -er et -ez se lisent souvent é : manger, chantez.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends é.</li><li>Cherche é dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null), 6, 'les-sons-k-et-f', 'Les sons k et f', 'Lire le son k (c, qu, q, k) et le son f (f et ph).', 6, 'published', 'Lecture', '[{"title":"Curriculum de l’Éducation de Base, Langue et communication, étape 1, 2e version (MEN, avril 2014)","url":"http://svtdakar.e-monsite.com/medias/files/1.-langue-et-communication-1-efa.pdf","kind":"official"},{"title":"Guide pédagogique, enseignement élémentaire, 1re étape CI-CP (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%201.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-k-et-f'), 1, 'le-son-k-c-qu-q-k', 'Le son k : c, qu, q, k', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-k-et-f') and slug = 'le-son-k-c-qu-q-k'), $html$<p>Écoute bien : on entend le son <strong>k</strong> dans « canard », « coq », « kilo ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>c (ca, co, cu) · qu · q · k</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>ca · co · cu · que · qui · ka</strong></p><p>Des mots : <strong>canard · école · coq · quatre · qui · képi</strong></p><p>Une phrase : <strong>Kader a quatre canards.</strong></p><h2>J’écris</h2><p>Devant e et i, j’écris qu pour garder le son k : qui, que.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends k.</li><li>Cherche k dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-k-et-f'), 2, 'le-son-f-f-et-ph', 'Le son f : f et ph', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-k-et-f') and slug = 'le-son-f-f-et-ph'), $html$<p>Écoute bien : on entend le son <strong>f</strong> dans « feu », « photo », « café ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>f · F · ph</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>fa · fi · fo · pha · pho · phi</strong></p><p>Des mots : <strong>fusée · farine · photo · phare · téléphone · Sophie</strong></p><p>Une phrase : <strong>Sophie a une photo du phare.</strong></p><h2>J’écris</h2><p>Les lettres p et h côte à côte se lisent f : photo, phare.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends f.</li><li>Cherche f dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null), 7, 'les-sons-eu-s-et-z', 'Les sons eu, s et z', 'Lire le son eu (eu, œu), le son s (s, ss, c, ç) et le s qui se lit z.', 7, 'published', 'Lecture', '[{"title":"Curriculum de l’Éducation de Base, Langue et communication, étape 1, 2e version (MEN, avril 2014)","url":"http://svtdakar.e-monsite.com/medias/files/1.-langue-et-communication-1-efa.pdf","kind":"official"},{"title":"Guide pédagogique, enseignement élémentaire, 1re étape CI-CP (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%201.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-eu-s-et-z'), 1, 'le-son-eu-eu-et-u', 'Le son eu : eu et œu', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-eu-s-et-z') and slug = 'le-son-eu-eu-et-u'), $html$<p>Écoute bien : on entend le son <strong>eu</strong> dans « feu », « cheveu », « sœur ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>eu · œu</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>peu · deu · neu · feu · veu · bleu</strong></p><p>Des mots : <strong>feu · deux · bleu · neveu · cheveu · sœur</strong></p><p>Une phrase : <strong>Il y a deux œufs dans le nid.</strong></p><h2>J’écris</h2><p>Dans œ, le o et le e sont collés : on les écrit sans lever le crayon.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends eu.</li><li>Cherche eu dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-eu-s-et-z'), 2, 'le-son-s-s-ss-c-c', 'Le son s : s, ss, c, ç', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-eu-s-et-z') and slug = 'le-son-s-s-ss-c-c'), $html$<p>Écoute bien : on entend le son <strong>s</strong> dans « sac », « poisson », « garçon ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>s · ss · c (ce, ci) · ç (ça, ço, çu)</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>sa · ssa · ce · ci · ça · ço</strong></p><p>Des mots : <strong>salade · poisson · tasse · cinéma · garçon · leçon</strong></p><p>Une phrase : <strong>Le garçon lit sa leçon dans le salon.</strong></p><h2>J’écris</h2><p>La cédille sous le c (ç) lui donne le son s devant a, o et u : ça, garçon, reçu.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends s.</li><li>Cherche s dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-eu-s-et-z'), 3, 'quand-s-se-lit-z', 'Quand s se lit z', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-eu-s-et-z') and slug = 'quand-s-se-lit-z'), $html$<p>Écoute bien : on entend le son <strong>z</strong> dans « maison », « rose », « zéro ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>z · s entre deux voyelles</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>za · zo · zé · zu · mai-son · ro-se</strong></p><p>Des mots : <strong>maison · rose · valise · oiseau · zéro · zébu</strong></p><p>Une phrase : <strong>La valise rose est dans la maison.</strong></p><h2>J’écris</h2><p>Un seul s entre deux voyelles se lit z : rose. Pour garder le son s, on écrit ss : poisson.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends z.</li><li>Cherche z dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null), 8, 'les-sons-g-j-et-gn', 'Les sons g, j et gn', 'Lire le son g (g, gu), le son j (j, ge, gi) et le son gn.', 8, 'published', 'Lecture', '[{"title":"Curriculum de l’Éducation de Base, Langue et communication, étape 1, 2e version (MEN, avril 2014)","url":"http://svtdakar.e-monsite.com/medias/files/1.-langue-et-communication-1-efa.pdf","kind":"official"},{"title":"Guide pédagogique, enseignement élémentaire, 1re étape CI-CP (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%201.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-g-j-et-gn'), 1, 'le-son-g-g-et-gu', 'Le son g : g et gu', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-g-j-et-gn') and slug = 'le-son-g-g-et-gu'), $html$<p>Écoute bien : on entend le son <strong>g</strong> dans « gâteau », « légume », « guitare ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>g (ga, go, gu) · gu (gue, gui)</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>ga · go · gu · gue · gui</strong></p><p>Des mots : <strong>gare · gomme · légume · bague · guitare · figue</strong></p><p>Une phrase : <strong>Guy mange une figue à la gare.</strong></p><h2>J’écris</h2><p>Devant e et i, j’ajoute un u pour garder le son g : bague, guitare.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends g.</li><li>Cherche g dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-g-j-et-gn'), 2, 'le-son-j-j-ge-gi', 'Le son j : j, ge, gi', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-g-j-et-gn') and slug = 'le-son-j-j-ge-gi'), $html$<p>Écoute bien : on entend le son <strong>j</strong> dans « jupe », « girafe », « page ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>j · g devant e, i, y (ge, gi)</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>ja · jo · ju · ge · gi</strong></p><p>Des mots : <strong>jupe · jaune · joli · girafe · page · magie</strong></p><p>Une phrase : <strong>Ma jupe jaune est jolie.</strong></p><h2>J’écris</h2><p>Devant e, i et y, la lettre g se lit j : girafe, page.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends j.</li><li>Cherche j dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-g-j-et-gn'), 3, 'le-son-gn', 'Le son gn', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-g-j-et-gn') and slug = 'le-son-gn'), $html$<p>Écoute bien : on entend le son <strong>gn</strong> dans « montagne », « peigne », « agneau ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>gn</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>gna · gne · gni · gno</strong></p><p>Des mots : <strong>ligne · signe · vigne · agneau · montagne · cygne</strong></p><p>Une phrase : <strong>L’agneau est sur la montagne.</strong></p><h2>J’écris</h2><p>Le g et le n ensemble se lisent gn, comme dans ligne.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends gn.</li><li>Cherche gn dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null), 9, 'les-sons-in-et-an', 'Les sons in et an', 'Lire le son in (in, ain, ein) et le son an (an, en, am, em).', 9, 'published', 'Lecture', '[{"title":"Curriculum de l’Éducation de Base, Langue et communication, étape 1, 2e version (MEN, avril 2014)","url":"http://svtdakar.e-monsite.com/medias/files/1.-langue-et-communication-1-efa.pdf","kind":"official"},{"title":"Guide pédagogique, enseignement élémentaire, 1re étape CI-CP (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%201.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-in-et-an'), 1, 'le-son-in-in-ain-ein', 'Le son in : in, ain, ein', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-in-et-an') and slug = 'le-son-in-in-ain-ein'), $html$<p>Écoute bien : on entend le son <strong>in</strong> dans « lapin », « pain », « peinture ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>in · ain · ein</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>pin · lin · main · pain · pein</strong></p><p>Des mots : <strong>lapin · sapin · matin · jardin · pain · main</strong></p><p>Une phrase : <strong>Le lapin mange du pain le matin.</strong></p><h2>J’écris</h2><p>Le son in s’écrit de trois façons : in, ain, ein. Je regarde bien le mot pour l’écrire.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends in.</li><li>Cherche in dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-in-et-an'), 2, 'le-son-an-an-en-am-em', 'Le son an : an, en, am, em', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-in-et-an') and slug = 'le-son-an-an-en-am-em'), $html$<p>Écoute bien : on entend le son <strong>an</strong> dans « maman », « enfant », « lampe ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>an · en · am · em</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>man · tan · ven · den · lam · tem</strong></p><p>Des mots : <strong>maman · enfant · lampe · dent · vent · chambre</strong></p><p>Une phrase : <strong>Maman range la lampe dans la chambre.</strong></p><h2>J’écris</h2><p>Devant m, b et p, on écrit am et em : lampe, chambre, temps.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends an.</li><li>Cherche an dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
