insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'ecrire-en-lettres-attachees') and slug = 'les-lettres-a-boucle-et-a-pont'), $html$<p>Au CP, on écrit surtout en <strong>lettres attachées</strong> (cursives) : les lettres d’un mot se tiennent la main.</p>
