insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'decrire-et-comparer') and slug = 'decrire-un-animal-ou-une-personne-et-comparer'), $html$<p>On peut décrire un animal ou une personne, puis les comparer.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null), 12, 'les-consonnes-doubles', 'Les consonnes doubles', 'Lire les groupes de deux consonnes : tr, pr, dr, br, cr, fr, gr puis fl, pl, gl, bl, cl.', 12, 'published', 'Lecture', '[{"title":"Curriculum de l’Éducation de Base, Langue et communication, étape 1, 2e version (MEN, avril 2014)","url":"http://svtdakar.e-monsite.com/medias/files/1.-langue-et-communication-1-efa.pdf","kind":"official"},{"title":"Guide pédagogique, enseignement élémentaire, 1re étape CI-CP (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%201.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-consonnes-doubles'), 1, 'tr-pr-dr-br-cr-fr-gr', 'tr, pr, dr, br, cr, fr, gr', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-consonnes-doubles') and slug = 'tr-pr-dr-br-cr-fr-gr'), $html$<p>Écoute bien : on entend le son <strong>r après une consonne</strong> dans « train », « prune », « arbre ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>tr · pr · dr · br · cr · fr · gr</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>tra · pré · dri · bro · cra · fru · gra</strong></p><p>Des mots : <strong>train · prune · drap · arbre · crabe · fruit · grand</strong></p><p>Une phrase : <strong>Le train passe près du grand arbre.</strong></p><h2>J’écris</h2><p>Je lis les deux consonnes ensemble, sans les séparer : tr-ain, pr-une.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends r après une consonne.</li><li>Cherche r après une consonne dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-consonnes-doubles'), 2, 'fl-pl-gl-bl-cl', 'fl, pl, gl, bl, cl', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-consonnes-doubles') and slug = 'fl-pl-gl-bl-cl'), $html$<p>Écoute bien : on entend le son <strong>l après une consonne</strong> dans « fleur », « plume », « table ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>fl · pl · gl · bl · cl</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>fla · plu · gli · blé · clo</strong></p><p>Des mots : <strong>fleur · plume · glace · table · clé · plage</strong></p><p>Une phrase : <strong>Sur la table, il y a une fleur et une clé.</strong></p><h2>J’écris</h2><p>Comme pour tr et pr, je lis les deux consonnes d’un seul coup : fl-eur, pl-ume.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends l après une consonne.</li><li>Cherche l après une consonne dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null), 13, 'les-sons-oir-eur-et-les-lettres-muettes', 'Les sons oir, eur et les lettres muettes', 'Lire ac, oir, eur, el, ec, puis repérer les lettres qu’on écrit sans les entendre.', 13, 'published', 'Lecture', '[{"title":"Curriculum de l’Éducation de Base, Langue et communication, étape 1, 2e version (MEN, avril 2014)","url":"http://svtdakar.e-monsite.com/medias/files/1.-langue-et-communication-1-efa.pdf","kind":"official"},{"title":"Guide pédagogique, enseignement élémentaire, 1re étape CI-CP (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%201.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-oir-eur-et-les-lettres-muettes'), 1, 'ac-oir-et-eur', 'ac, oir et eur', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-oir-eur-et-les-lettres-muettes') and slug = 'ac-oir-et-eur'), $html$<p>Écoute bien : on entend le son <strong>oir et eur</strong> dans « sac », « miroir », « fleur ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>ac · oir · eur</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>lac · sac · voir · soir · peur · leur</strong></p><p>Des mots : <strong>lac · sac · miroir · couloir · chanteur · moteur</strong></p><p>Une phrase : <strong>Ce soir, le chanteur se voit dans le miroir.</strong></p><h2>J’écris</h2><p>À la fin de oir et eur, j’entends bien le r : je ne l’oublie pas.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends oir et eur.</li><li>Cherche oir et eur dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-oir-eur-et-les-lettres-muettes'), 2, 'el-ec-es-et-les-lettres-muettes', 'el, ec, es et les lettres muettes', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-oir-eur-et-les-lettres-muettes') and slug = 'el-ec-es-et-les-lettres-muettes'), $html$<p>Certaines lettres s’entendent, d’autres sont <strong>muettes</strong> : on les écrit, mais on ne les entend pas.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null), 14, 'donner-des-ordres-et-interdire', 'Donner des ordres et interdire', 'Donner un ordre ou une consigne, puis interdire quelque chose poliment.', 14, 'published', 'Communication orale', '[{"title":"Curriculum de l’Éducation de Base, Langue et communication, étape 1, 2e version (MEN, avril 2014)","url":"http://svtdakar.e-monsite.com/medias/files/1.-langue-et-communication-1-efa.pdf","kind":"official"},{"title":"Guide pédagogique, enseignement élémentaire, 1re étape CI-CP (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%201.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'donner-des-ordres-et-interdire'), 1, 'donner-une-consigne', 'Donner une consigne', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'donner-des-ordres-et-interdire') and slug = 'donner-une-consigne'), $html$<p>Pour faire faire quelque chose, on donne une <strong>consigne</strong> avec un verbe d’action.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'donner-des-ordres-et-interdire'), 2, 'interdire-quelque-chose', 'Interdire quelque chose', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'donner-des-ordres-et-interdire') and slug = 'interdire-quelque-chose'), $html$<p>Pour <strong>interdire</strong>, on dit ce qu’il ne faut pas faire, et on explique pourquoi.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null), 15, 'les-sons-ette-elle-et-ill', 'Les sons ette, elle et ill', 'Lire -ette, -erre, -esse, -elle, -enne, puis ill, ail, eil, euil, ouil.', 15, 'published', 'Lecture', '[{"title":"Curriculum de l’Éducation de Base, Langue et communication, étape 1, 2e version (MEN, avril 2014)","url":"http://svtdakar.e-monsite.com/medias/files/1.-langue-et-communication-1-efa.pdf","kind":"official"},{"title":"Guide pédagogique, enseignement élémentaire, 1re étape CI-CP (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%201.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-ette-elle-et-ill'), 1, 'ette-erre-esse-elle-enne', '-ette, -erre, -esse, -elle, -enne', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-ette-elle-et-ill') and slug = 'ette-erre-esse-elle-enne'), $html$<p>Écoute bien : on entend le son <strong>è devant deux consonnes</strong> dans « lunette », « terre », « pelle ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>ette · erre · esse · elle · enne</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>nette · terre · tesse · belle · tenne</strong></p><p>Des mots : <strong>lunette · terre · pierre · maîtresse · pelle · antenne</strong></p><p>Une phrase : <strong>La maîtresse range la pelle près de la pierre.</strong></p><h2>J’écris</h2><p>Devant deux consonnes pareilles (tt, rr, ss, ll, nn), le e se lit è.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends è devant deux consonnes.</li><li>Cherche è devant deux consonnes dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-ette-elle-et-ill'), 2, 'ill-ail-eil-euil-ouil', 'ill, ail, eil, euil, ouil', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-ette-elle-et-ill') and slug = 'ill-ail-eil-euil-ouil'), $html$<p>Écoute bien : on entend le son <strong>ill</strong> dans « fille », « soleil », « grenouille ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>ill · ail · aill · eil · eill · euil · ouil · ouill</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>bille · ail · eil · euil · ouille</strong></p><p>Des mots : <strong>fille · bille · travail · soleil · fauteuil · grenouille</strong></p><p>Une phrase : <strong>La fille joue aux billes au soleil.</strong></p><h2>J’écris</h2><p>À la fin d’un mot, ail, eil et euil s’écrivent avec un seul l ; au milieu, on double le l : travailler, oreille.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends ill.</li><li>Cherche ill dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null), 16, 'les-sons-ier-ieu-ien-ui-oin-et-ion', 'Les sons ier, ieu, ien, ui, oin et ion', 'Lire y (= deux i), ier, iez, iau, ieu, ien, puis ui, oin, ion, et sc, st, sp, h, x.', 16, 'published', 'Lecture', '[{"title":"Curriculum de l’Éducation de Base, Langue et communication, étape 1, 2e version (MEN, avril 2014)","url":"http://svtdakar.e-monsite.com/medias/files/1.-langue-et-communication-1-efa.pdf","kind":"official"},{"title":"Guide pédagogique, enseignement élémentaire, 1re étape CI-CP (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%201.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-ier-ieu-ien-ui-oin-et-ion'), 1, 'y-ier-ieu-et-ien', 'y, ier, ieu et ien', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-ier-ieu-ien-ui-oin-et-ion') and slug = 'y-ier-ieu-et-ien'), $html$<p>Écoute bien : on entend le son <strong>i suivi d’un autre son</strong> dans « crayon », « panier », « chien ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>y (= deux i, comme dans crayon) · ier · iez · iau · ieu · ien</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>yon · pier · nier · mieu · bien · chien</strong></p><p>Des mots : <strong>crayon · papier · cahier · panier · mieux · chien</strong></p><p>Une phrase : <strong>Le chien dort dans le panier.</strong></p><h2>J’écris</h2><p>Je lis i et le son qui suit d’un seul coup : pa-nier, chien.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends i suivi d’un autre son.</li><li>Cherche i suivi d’un autre son dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-ier-ieu-ien-ui-oin-et-ion'), 2, 'ui-oin-ion-et-les-lettres-h-et-x', 'ui, oin, ion et les lettres h et x', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'les-sons-ier-ieu-ien-ui-oin-et-ion') and slug = 'ui-oin-ion-et-les-lettres-h-et-x'), $html$<p>Écoute bien : on entend le son <strong>ui, oin, ion</strong> dans « nuit », « loin », « camion ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>ui · oin · ion (et sc, st, sp ; h muet ; x)</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>nui · fui · loin · coin · lion · tion</strong></p><p>Des mots : <strong>nuit · fruit · point · camion · lion · taxi</strong></p><p>Une phrase : <strong>La nuit, le camion roule loin.</strong></p><h2>J’écris</h2><p>Le h au début d’un mot ne se prononce pas : hibou, histoire. Le x se lit souvent ks : taxi.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends ui, oin, ion.</li><li>Cherche ui, oin, ion dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null), 17, 'ecrire-de-petits-textes', 'Écrire de petits textes', 'Écrire au moins deux phrases pour raconter, décrire ou donner des consignes.', 17, 'published', 'Production d’écrits', '[{"title":"Curriculum de l’Éducation de Base, Langue et communication, étape 1, 2e version (MEN, avril 2014)","url":"http://svtdakar.e-monsite.com/medias/files/1.-langue-et-communication-1-efa.pdf","kind":"official"},{"title":"Guide pédagogique, enseignement élémentaire, 1re étape CI-CP (Curriculum de l’Éducation de Base, MEN)","url":"https://www.apams.gouv.sn/sites/default/files/GUIDE%20PEDAGOGIQUE%20ETAPE%201.pdf","kind":"official"},{"title":"Leçons rédigées par DIANGAL, à faire relire par un enseignant","kind":"diangal"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'ecrire-de-petits-textes'), 1, 'raconter-par-ecrit', 'Raconter par écrit', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CP' and p.series_id is null) and c.slug = 'ecrire-de-petits-textes') and slug = 'raconter-par-ecrit'), $html$<p>Au CP, tu écris de petits textes d’<strong>au moins deux phrases</strong>.</p>
