insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = '3E' and p.series_id is null) and c.slug = 'le-discours-rapporte') and slug = 'passer-du-direct-a-l-indirect'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Changer les pronoms et les possessifs (je → il, mon → son).</li><li>Concordance des temps si le verbe introducteur est au passé (présent → imparfait, futur → conditionnel).</li><li>Adapter les indicateurs de temps et de lieu (demain → le lendemain, ici → là).</li></ol></div>
