insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'ANG' and l.code = '3E' and p.series_id is null) and c.slug = 'present-simple-and-continuous') and slug = 'simple-or-continuous'), $html$<ul><li>Key words for the present simple: always, usually, often, every day, on Mondays.</li><li>Key words for the present continuous: now, at the moment, look!, listen!</li><li>Some verbs are not used in the continuous: like, love, know, want, understand.</li></ul>
