insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'l-imperialisme-europeen-et-le-partage-de-l-afrique') and slug = 'la-conference-de-berlin'), $html$<p>De novembre 1884 à février 1885, la <strong>conférence de Berlin</strong> réunit les puissances européennes. Aucun Africain n’y participe.</p>
