insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'l-imperialisme-europeen-et-le-partage-de-l-afrique') and slug = 'les-systemes-coloniaux'), $html$<table><thead><tr><th scope="col"></th><th scope="col">France</th><th scope="col">Grande-Bretagne</th></tr></thead><tbody><tr><td>Principe</td><td>administration directe, assimilation</td><td>administration indirecte (indirect rule)</td></tr><tr><td>Chefs locaux</td><td>simples auxiliaires</td><td>gardent une partie du pouvoir</td></tr><tr><td>Exemple</td><td>AOF, créée en 1895 (capitale Dakar à partir de 1902)</td><td>Nigeria, Gold Coast</td></tr></tbody></table>
