insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'les-resistances-africaines') and slug = 'les-resistances-armees'), $html$<ul><li><strong>El Hadj Omar Tall</strong> combat les Français (siège de Médine, 1857).</li><li><strong>Lat Dior Diop</strong>, damel du Cayor, s’oppose au chemin de fer Dakar–Saint-Louis ; il meurt à Dekhelé en 1886.</li><li><strong>Samory Touré</strong> résiste plus de quinze ans avant d’être capturé en 1898.</li><li><strong>Ménélik II</strong> bat les Italiens à Adoua (1896) : l’Éthiopie reste indépendante.</li></ul>$html$);
