insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'les-resistances-africaines') and slug = 'les-resistances-pacifiques-et-religieuses'), $html$<ul><li><strong>Cheikh Ahmadou Bamba</strong>, fondateur du mouridisme, prône une résistance spirituelle ; il est déporté au Gabon en 1895.</li><li><strong>Aline Sitoé Diatta</strong>, en Casamance, appelle à refuser les réquisitions coloniales ; elle est arrêtée en 1943.</li><li>Refus de l’impôt, fuite devant le travail forcé, maintien des cultures et des langues.</li></ul>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'les-resistances-africaines'), 3, 'le-bilan-des-resistances', 'Le bilan des résistances', false, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'les-resistances-africaines') and slug = 'le-bilan-des-resistances'), $html$<p>Malgré leur courage, la plupart des résistants sont vaincus : supériorité des armes européennes, divisions entre royaumes africains, alliances des colonisateurs avec certains chefs.</p>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null), 4, 'l-imperialisme-en-asie-et-en-amerique', 'L’impérialisme en Asie et en Amérique', 'Impérialismes européen et japonais en Asie, impérialisme américain.', 4, 'published', null, '[{"title":"Relevé DIANGAL du programme de 3e (PROMET, titres de chapitres de Sunudaara)","kind":"external"}]'::jsonb);
