insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'l-imperialisme-en-asie-et-en-amerique') and slug = 'les-europeens-en-asie'), $html$<ul><li><strong>Inde</strong> : sous domination britannique, elle devient colonie de la Couronne en 1858.</li><li><strong>Chine</strong> : après les guerres de l’opium (1839-1842, 1856-1860), elle doit signer des « traités inégaux » et ouvrir ses ports.</li><li><strong>Indochine</strong> : la France forme l’Union indochinoise en 1887.</li></ul>$html$);
