insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'l-imperialisme-en-asie-et-en-amerique'), 3, 'l-imperialisme-americain', 'L’impérialisme américain', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'l-imperialisme-en-asie-et-en-amerique') and slug = 'l-imperialisme-americain'), $html$<ul><li>La <strong>doctrine Monroe</strong> (1823) : l’Amérique aux Américains, les Européens ne doivent pas y intervenir.</li><li>Après la guerre contre l’Espagne (1898), les États-Unis contrôlent Cuba et les Philippines.</li><li>Ils construisent le canal de Panama (ouvert en 1914) et interviennent en Amérique latine (« politique du gros bâton »).</li></ul>$html$);
