insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'la-premiere-guerre-mondiale') and slug = 'les-causes-de-la-guerre'), $html$<ul><li>Rivalités économiques et coloniales entre puissances européennes.</li><li>Nationalismes et course aux armements.</li><li>Deux blocs : la Triple Entente (France, Royaume-Uni, Russie) et la Triple Alliance (Allemagne, Autriche-Hongrie, Italie).</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'la-premiere-guerre-mondiale'), 2, 'le-deroulement-du-conflit', 'Le déroulement du conflit', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'la-premiere-guerre-mondiale') and slug = 'le-deroulement-du-conflit'), $html$<ul><li>1914 : guerre de mouvement, puis le front se fige.</li><li>1915-1917 : guerre des tranchées (Verdun en 1916).</li><li>1917 : entrée en guerre des États-Unis ; la Russie se retire.</li><li>11 novembre 1918 : armistice.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'la-premiere-guerre-mondiale'), 3, 'les-consequences', 'Les conséquences', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'la-premiere-guerre-mondiale') and slug = 'les-consequences'), $html$<ul><li>Environ 10 millions de soldats morts, des régions dévastées.</li><li>Le traité de Versailles (1919) impose de lourdes conditions à l’Allemagne.</li><li>Création de la <strong>Société des Nations</strong> (SDN) pour garantir la paix.</li><li>Les colonies allemandes (Togo, Cameroun…) sont confiées à la France et au Royaume-Uni.</li></ul>$html$);
