insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'la-revolution-russe'), 1, 'les-revolutions-de-1917', 'Les révolutions de 1917', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'la-revolution-russe') and slug = 'les-revolutions-de-1917'), $html$<ul><li>Russie de 1914 : empire du tsar Nicolas II, paysans pauvres, défaites militaires.</li><li><strong>Février 1917</strong> : le tsar abdique ; un gouvernement provisoire se forme.</li><li><strong>Octobre 1917</strong> : les bolcheviks de Lénine prennent le pouvoir.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'la-revolution-russe'), 2, 'la-construction-de-l-urss', 'La construction de l’URSS', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'la-revolution-russe') and slug = 'la-construction-de-l-urss'), $html$<ul><li>1918-1921 : guerre civile entre « rouges » et « blancs ».</li><li>1921 : la NEP (nouvelle politique économique) autorise un peu de commerce privé.</li><li>1922 : naissance de l’<strong>URSS</strong>.</li><li>Après la mort de Lénine (1924), <strong>Staline</strong> impose la collectivisation des terres, les plans quinquennaux et un régime de terreur.</li></ul>
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status, strand, sources) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null), 7, 'la-crise-des-annees-1930', 'La crise des années 1930', 'Le krach de 1929 et ses conséquences dans le monde.', 7, 'published', null, '[{"title":"Relevé DIANGAL du programme de 3e (PROMET, titres de chapitres de Sunudaara)","kind":"external"}]'::jsonb);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'la-crise-des-annees-1930'), 1, 'le-krach-de-1929', 'Le krach de 1929', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'la-crise-des-annees-1930') and slug = 'le-krach-de-1929'), $html$<p>Le jeudi 24 octobre 1929 (« jeudi noir »), la Bourse de New York s’effondre : c’est le <strong>krach de Wall Street</strong>.</p>
