insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'la-seconde-guerre-mondiale') and slug = 'le-deroulement'), $html$<ul><li>1939-1942 : victoires de l’Axe ; la France est battue en juin 1940.</li><li>1941 : l’Allemagne attaque l’URSS ; le Japon attaque Pearl Harbor, les États-Unis entrent en guerre.</li><li>1942-1943 : tournants (Stalingrad, El Alamein).</li><li>1944 : débarquement en Normandie ; 8 mai 1945 : capitulation de l’Allemagne ; septembre 1945 : capitulation du Japon après les bombes atomiques.</li></ul>
