insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'HG' and l.code = '3E' and p.series_id is null) and c.slug = 'le-senegal-de-1944-a-1962') and slug = 'les-reformes-d-apres-guerre'), $html$<ul><li>1944 : la conférence de Brazzaville promet des réformes, sans parler d’indépendance.</li><li>1946 : la loi Houphouët-Boigny abolit le travail forcé ; la loi Lamine Guèye donne la citoyenneté française à tous les habitants des colonies.</li><li>1948 : Léopold Sédar Senghor fonde le Bloc démocratique sénégalais (BDS).</li><li>1956 : la loi-cadre Defferre accorde une autonomie interne.</li></ul>$html$);
