insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '3E' and p.series_id is null) and c.slug = 'le-systeme-nerveux') and slug = 'l-organisation-du-systeme-nerveux'), $html$<ul><li>Le <strong>système nerveux central</strong> : l’encéphale (cerveau, cervelet, bulbe rachidien), protégé par le crâne, et la moelle épinière, protégée par la colonne vertébrale.</li><li>Le <strong>système nerveux périphérique</strong> : les nerfs, qui relient les centres nerveux aux organes.</li></ul>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '3E' and p.series_id is null) and c.slug = 'le-systeme-nerveux'), 2, 'le-reflexe', 'Le réflexe', false, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '3E' and p.series_id is null) and c.slug = 'le-systeme-nerveux') and slug = 'le-reflexe'), $html$<p>Un <strong>réflexe</strong> est une réaction involontaire, rapide et toujours identique à une stimulation : retirer la main d’une marmite brûlante, le réflexe rotulien.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '3E' and p.series_id is null) and c.slug = 'le-systeme-nerveux'), 3, 'l-acte-volontaire-et-l-hygiene', 'L’acte volontaire et l’hygiène', false, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '3E' and p.series_id is null) and c.slug = 'le-systeme-nerveux') and slug = 'l-acte-volontaire-et-l-hygiene'), $html$<p>Un <strong>acte volontaire</strong> (écrire, shooter dans un ballon) est décidé par le cerveau. Le message part du cortex cérébral, descend par la moelle épinière et atteint les muscles par les nerfs moteurs.</p>
