insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '3E' and p.series_id is null) and c.slug = 'la-vision'), 1, 'l-il-organe-de-la-vision', 'L’œil, organe de la vision', false, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '3E' and p.series_id is null) and c.slug = 'la-vision') and slug = 'l-il-organe-de-la-vision'), $html$<ul><li>La <strong>cornée</strong>, transparente, laisse entrer la lumière.</li><li>L’<strong>iris</strong> (partie colorée) règle l’ouverture de la <strong>pupille</strong>.</li><li>Le <strong>cristallin</strong> est une lentille convergente souple.</li><li>La <strong>rétine</strong>, au fond de l’œil, contient les cellules sensibles à la lumière.</li><li>Le <strong>nerf optique</strong> transmet les messages au cerveau.</li></ul>
