insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '3E' and p.series_id is null) and c.slug = 'la-tectonique-des-plaques') and slug = 'les-mouvements-des-plaques'), $html$<ul><li><strong>Divergence</strong> : au niveau des dorsales océaniques, les plaques s’écartent et un nouveau plancher océanique se forme (l’Atlantique s’élargit).</li><li><strong>Convergence</strong> : une plaque océanique plonge sous une autre (<strong>subduction</strong>) ; volcans explosifs et séismes. Quand deux continents se heurtent, des montagnes se forment (Himalaya).</li><li><strong>Coulissage</strong> : les plaques glissent l’une contre l’autre (faille de San Andreas).</li></ul>
