insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'SVT' and l.code = '3E' and p.series_id is null) and c.slug = 'les-roches-metamorphiques') and slug = 'qu-est-ce-que-le-metamorphisme'), $html$<p>Le <strong>métamorphisme</strong> est la transformation d’une roche, à l’état solide, sous l’effet d’une forte <strong>température</strong> et d’une forte <strong>pression</strong>, en profondeur (zones de collision, enfouissement).</p>
