insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '3E' and p.series_id is null) and c.slug = 'les-lentilles-minces') and slug = 'construire-l-image-d-un-objet'), $html$<div class="callout"><p class="callout-title">Méthode</p><ol><li>Tracer l’axe optique, la lentille, les foyers F et F’ à la même distance de O.</li><li>Depuis le sommet B de l’objet AB, tracer deux des trois rayons particuliers.</li><li>Leur point de rencontre est B’, image de B ; A’ est sur l’axe, à la verticale de B’.</li></ol></div>
