insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '3E' and p.series_id is null) and c.slug = 'la-dispersion-de-la-lumiere-blanche') and slug = 'le-prisme-decompose-la-lumiere'), $html$<p>Un faisceau de lumière blanche (soleil, lampe) qui traverse un <strong>prisme</strong> en verre est dévié et étalé en une bande colorée : le <strong>spectre</strong>.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '3E' and p.series_id is null) and c.slug = 'la-dispersion-de-la-lumiere-blanche'), 2, 'recomposition-et-arc-en-ciel', 'Recomposition et arc-en-ciel', false, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '3E' and p.series_id is null) and c.slug = 'la-dispersion-de-la-lumiere-blanche') and slug = 'recomposition-et-arc-en-ciel'), $html$<p>Si on fait passer le spectre dans un second prisme retourné, ou si on fait tourner vite un disque peint aux couleurs du spectre (disque de Newton), on retrouve du blanc : c’est la <strong>recomposition</strong> de la lumière blanche.</p>
