insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '3E' and p.series_id is null) and c.slug = 'les-forces') and slug = 'effets-et-caracteristiques-d-une-force'), $html$<p>Une <strong>force</strong> modélise une action mécanique. Elle peut mettre un objet en mouvement, modifier son mouvement ou le déformer.</p>
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '3E' and p.series_id is null) and c.slug = 'les-forces'), 2, 'le-poids-d-un-corps', 'Le poids d’un corps', false, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '3E' and p.series_id is null) and c.slug = 'les-forces') and slug = 'le-poids-d-un-corps'), $html$<p>Le <strong>poids</strong> est la force d’attraction exercée par la Terre sur un objet. Il est vertical, dirigé vers le bas, appliqué au centre de gravité.</p>
