insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '3E' and p.series_id is null) and c.slug = 'l-equilibre-d-un-solide-soumis-a-deux-forces'), 2, 'applications-fil-support-ressort', 'Applications : fil, support, ressort', true, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'PC' and l.code = '3E' and p.series_id is null) and c.slug = 'l-equilibre-d-un-solide-soumis-a-deux-forces') and slug = 'applications-fil-support-ressort'), $html$<ul><li><strong>Objet suspendu à un fil</strong> : la tension T du fil compense le poids P. T = P, et le fil est vertical.</li><li><strong>Objet posé sur une table</strong> : la réaction R de la table compense le poids. R = P.</li><li><strong>Ressort</strong> : son allongement est proportionnel à la force qui le tire (dans la limite d’élasticité).</li></ul>
