insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'EC' and l.code = '3E' and p.series_id is null) and c.slug = 'les-institutions-de-la-republique') and slug = 'la-separation-des-pouvoirs'), $html$<table><thead><tr><th scope="col">Pouvoir</th><th scope="col">Rôle</th><th scope="col">Institution</th></tr></thead><tbody><tr><td>Exécutif</td><td>applique les lois, dirige l’État</td><td>le président de la République et le Gouvernement</td></tr><tr><td>Législatif</td><td>vote les lois et le budget, contrôle le Gouvernement</td><td>l’Assemblée nationale</td></tr><tr><td>Judiciaire</td><td>rend la justice</td><td>les cours et tribunaux</td></tr></tbody></table>
