insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'EC' and l.code = '3E' and p.series_id is null) and c.slug = 'la-democratie-et-les-elections') and slug = 'les-principes-de-la-democratie'), $html$<p>La <strong>démocratie</strong> est le pouvoir du peuple, par le peuple et pour le peuple. Le peuple choisit ses dirigeants par des élections libres.</p>
